-- TABLE: log_opname
DROP TABLE IF EXISTS "log_opname" CASCADE;
CREATE TABLE "log_opname" (
  "id_opname" TEXT,
  "waktu_opname" TEXT,
  "id_obat" TEXT,
  "satuan" TEXT,
  "stok_sistem" TEXT,
  "stok_fisik" TEXT,
  "selisih" TEXT,
  "ed_fisik_opname" TEXT,
  "keterangan" TEXT,
  "petugas" TEXT
);

-- VIEW: view_low_stock
CREATE OR REPLACE VIEW view_low_stock AS
SELECT 
    id_obat, 
    nama_obat, 
    stok_unit_kecil, 
    stok_minimal, 
    label_satuan_kecil
FROM master_obat
WHERE 
    stok_minimal IS NOT NULL 
    AND stok_minimal != '' 
    AND stok_minimal ~ '^[0-9.-]+$'
    AND stok_unit_kecil ~ '^[0-9.-]+$'
    AND CAST(stok_minimal AS NUMERIC) > 0
    AND CAST(stok_unit_kecil AS NUMERIC) <= CAST(stok_minimal AS NUMERIC);

-- VIEW: view_stok_realtime
CREATE OR REPLACE VIEW view_stok_realtime AS
WITH in_stock AS (
    SELECT id_obat, COALESCE(SUM(CASE WHEN konversi_masuk ~ '^[0-9.-]+$' THEN CAST(konversi_masuk AS NUMERIC) ELSE 0 END), 0) AS total_in
    FROM log_beli WHERE jenis_transaksi IN ('PEMBELIAN', 'STOK AWAL', 'KONSINYASI MASUK') GROUP BY id_obat
),
out_stock AS (
    SELECT id_obat, COALESCE(SUM(CASE WHEN konversi_keluar ~ '^[0-9.-]+$' THEN CAST(konversi_keluar AS NUMERIC) ELSE 0 END), 0) AS total_out
    FROM detail_jual WHERE jenis_transaksi = 'PENJUALAN' OR jenis_transaksi IS NULL OR jenis_transaksi = '' GROUP BY id_obat
),
retur_jual_stock AS (
    SELECT id_obat, COALESCE(SUM(CASE WHEN konversi_keluar ~ '^[0-9.-]+$' THEN CAST(konversi_keluar AS NUMERIC) ELSE 0 END), 0) AS total_retur_jual
    FROM detail_jual WHERE jenis_transaksi = 'RETUR PENJUALAN' GROUP BY id_obat
),
retur_beli_stock AS (
    SELECT id_obat, COALESCE(SUM(CASE WHEN konversi_masuk ~ '^[0-9.-]+$' THEN CAST(konversi_masuk AS NUMERIC) ELSE 0 END), 0) AS total_retur_beli
    FROM log_beli WHERE jenis_transaksi IN ('RETUR PEMBELIAN', 'RETUR KONSINYASI') GROUP BY id_obat
),
latest_ed AS (
    SELECT id_obat, MAX(expired_date) AS latest_ed
    FROM log_beli WHERE expired_date IS NOT NULL AND expired_date != '' AND expired_date != '-' GROUP BY id_obat
)
SELECT 
    m.*,
    COALESCE(ed.latest_ed, m.ed_terdekat) AS expired_date,
    CASE 
        WHEN m.jenis_item = 'JASA' THEN 0
        ELSE (
            COALESCE(CASE WHEN m.stok_dasar_opname ~ '^[0-9.-]+$' THEN CAST(m.stok_dasar_opname AS NUMERIC) ELSE 0 END, 0)
            + COALESCE(ins.total_in, 0)
            + COALESCE(rjs.total_retur_jual, 0)
            - COALESCE(outs.total_out, 0)
            - COALESCE(rbs.total_retur_beli, 0)
        )
    END AS stok_realtime
FROM master_obat m
LEFT JOIN in_stock ins ON m.id_obat = ins.id_obat
LEFT JOIN out_stock outs ON m.id_obat = outs.id_obat
LEFT JOIN retur_jual_stock rjs ON m.id_obat = rjs.id_obat
LEFT JOIN retur_beli_stock rbs ON m.id_obat = rbs.id_obat
LEFT JOIN latest_ed ed ON m.id_obat = ed.id_obat;

